// ======================================================
// TƯƠNG THÍCH BÀI TẬP/BÀI NỘP CŨ PHÍA HỌC SINH
// ======================================================
function studentCompatText(value) {
    return String(value ?? '').trim();
}

function getStudentCompatAssignmentIds(assignmentOrId) {
    const values =
        assignmentOrId &&
            typeof assignmentOrId === 'object'
            ? [
                assignmentOrId.id,
                assignmentOrId._fbKey,
                assignmentOrId.assignmentId,
                assignmentOrId.assignmentKey,
                assignmentOrId.key
            ]
            : [assignmentOrId];

    return [...new Set(
        values
            .map(studentCompatText)
            .filter(Boolean)
    )];
}

function getStudentCompatSubmissionAssignmentId(submission) {
    return studentCompatText(
        submission?.assignmentId ??
        submission?.assignId ??
        submission?.assignmentKey ??
        submission?.taskId ??
        submission?.exerciseId
    );
}

function getStudentCompatSubmissionUsername(submission) {
    return studentCompatText(
        submission?.studentUsername ??
        submission?.username ??
        submission?.studentUser ??
        submission?.studentId
    );
}

// ======================================================
// PHẠM VI LÀM LẠI + LỊCH SỬ VI PHẠM
// ======================================================
function getStudentRedoViolationHistory(submission) {
    const raw =
        submission &&
        typeof submission.redoViolationHistory === 'object' &&
        submission.redoViolationHistory !== null
            ? submission.redoViolationHistory
            : {};

    return {
        essayMissing: !!raw.essayMissing,
        late: !!raw.late,
        autoSubmitted: !!raw.autoSubmitted,
        cheat: !!raw.cheat
    };
}

function isStudentRedoViolationHistoryActive(submission) {
    if (!submission) return false;
    if (submission.redoViolationHistoryActive === false) return false;
    if (submission.redoViolationResolvedAt) return false;
    return true;
}

function getStudentActiveRedoViolationHistory(submission) {
    return isStudentRedoViolationHistoryActive(submission)
        ? getStudentRedoViolationHistory(submission)
        : {
            essayMissing: false,
            late: false,
            autoSubmitted: false,
            cheat: false
        };
}

function mergeStudentRedoViolationHistory(submission) {
    const history = getStudentRedoViolationHistory(
        submission
    );

    return {
        essayMissing:
            history.essayMissing ||
            !!submission?.isEssayMissing,
        late:
            history.late ||
            !!submission?.isLateFail,
        autoSubmitted:
            history.autoSubmitted ||
            !!submission?.isAutoSubmitted,
        cheat:
            history.cheat ||
            !!submission?.isCheatFail
    };
}

function hasStudentHistoricalViolation(submission) {
    const history = getStudentRedoViolationHistory(submission);

    return !!(
        history.essayMissing ||
        history.late ||
        history.autoSubmitted ||
        history.cheat
    );
}

function hasStudentCurrentViolation(submission) {
    return !!(
        submission &&
        (
            submission.isEssayMissing ||
            submission.isLateFail ||
            submission.isAutoSubmitted ||
            submission.isCheatFail
        )
    );
}

function hasStudentAnyViolation(submission) {
    return hasStudentCurrentViolation(submission) ||
        hasStudentHistoricalViolation(submission);
}


// ======================================================
// HUY HIỆU "NỘP TRỄ" CHO BÀI TỰ THU ĐÃ LÀM ĐỦ
// Chỉ gắn khi hệ thống tự thu sau hạn và phần bắt buộc đã hoàn thành.
// ======================================================
function isStudentCompleteLateAutoSubmission(
    submission,
    assignment
) {
    if (
        !submission?.isAutoSubmitted ||
        !submission?.isLateFail ||
        submission?.isCheatFail
    ) {
        return false;
    }

    // Bản ghi mới lưu kết quả kiểm tra ngay lúc tự thu.
    if (submission.isLateComplete === true) {
        return true;
    }

    if (submission.isLateComplete === false) {
        return false;
    }

    // Tương thích bản ghi cũ chưa có isLateComplete.
    const type = String(
        assignment?.assessmentType ||
        'tu_luan'
    );

    const questions =
        Array.isArray(submission?.questionSnapshot) &&
        submission.questionSnapshot.length > 0
            ? submission.questionSnapshot
            : (
                Array.isArray(assignment?.questions)
                    ? assignment.questions
                    : []
            );

    const mcAnswers =
        submission?.mcAnswers &&
        typeof submission.mcAnswers === 'object'
            ? submission.mcAnswers
            : {};

    const requiresMultipleChoice =
        type === 'trac_nghiem' ||
        type === 'ket_hop' ||
        type === 'thi';

    const multipleChoiceComplete =
        !requiresMultipleChoice ||
        (
            questions.length > 0 &&
            questions.every((question, index) => {
                const value =
                    mcAnswers[index] ??
                    mcAnswers[String(index)] ??
                    '';

                return String(value).trim() !== '';
            })
        );

    const requiresEssay =
        type !== 'trac_nghiem';

    let essayComplete = true;

    if (requiresEssay) {
        const files = Array.isArray(submission?.file)
            ? submission.file
            : (
                submission?.file
                    ? [submission.file]
                    : []
            );

        const hasFile = files.length > 0;
        const rawEssay = String(
            submission?.rawEssay ||
            ''
        ).trim();

        const wordCount = rawEssay
            ? rawEssay
                .split(/\s+/)
                .filter(Boolean)
                .length
            : 0;

        essayComplete = assignment?.hideEssayText
            ? hasFile
            : (
                wordCount >= 25 ||
                hasFile
            );
    }

    return (
        multipleChoiceComplete &&
        essayComplete &&
        !submission?.isEssayMissing
    );
}

function getStudentRedoScope(submission, assignment) {
    if (!submission?.isRedoing) {
        return 'both';
    }

    const raw = String(
        submission.redoScope ||
        'both'
    ).toLowerCase();

    if (
        raw === 'essay' ||
        raw === 'mc' ||
        raw === 'both'
    ) {
        return raw;
    }

    // Bài làm lại cũ chưa có redoScope: giữ hành vi cũ, mở toàn bộ.
    return 'both';
}

function studentRedoAllowsMultipleChoice(
    submission,
    assignment
) {
    if (!submission?.isRedoing) return true;

    const scope = getStudentRedoScope(
        submission,
        assignment
    );

    return scope === 'mc' || scope === 'both';
}

function studentRedoAllowsEssay(
    submission,
    assignment
) {
    if (!submission?.isRedoing) return true;

    const scope = getStudentRedoScope(
        submission,
        assignment
    );

    return scope === 'essay' || scope === 'both';
}

function getStudentRedoScopeLabel(scope) {
    if (scope === 'essay') return 'chỉ phần Tự luận';
    if (scope === 'mc') return 'chỉ phần Trắc nghiệm';
    return 'cả Trắc nghiệm và Tự luận';
}

function getStudentStoredExamSet(submission, assignment) {
    const storedQuestions =
        Array.isArray(submission?.questionSnapshot) &&
        submission.questionSnapshot.length > 0
            ? submission.questionSnapshot
            : null;

    if (storedQuestions) {
        return {
            questions: storedQuestions,
            versionCode:
                submission?.examVersionCode ||
                'Gốc',
            versionIndex:
                Number(
                    submission?.examVersionIndex
                ) || 0,
            randomized:
                Boolean(
                    submission?.examVersionCode &&
                    submission.examVersionCode !== 'Gốc'
                )
        };
    }

    return window.getStudentExamQuestions(
        assignment
    );
}

function getStudentStoredMultipleChoiceText(
    submission,
    assignment,
    examSet
) {
    const existingAnswer = String(
        submission?.answer ||
        ''
    );

    const storedMatch = existingAnswer.match(
        /\[PHẦN TRẮC NGHIỆM\]\s*([\s\S]*?)(?=\n{2,}\[PHẦN TỰ LUẬN\]|$)/i
    );

    if (storedMatch?.[1]?.trim()) {
        return storedMatch[1].trim();
    }

    const questions =
        Array.isArray(examSet?.questions)
            ? examSet.questions
            : [];

    const answers =
        submission?.mcAnswers &&
        typeof submission.mcAnswers === 'object'
            ? submission.mcAnswers
            : {};

    if (questions.length === 0) {
        return '';
    }

    let score = 0;
    const lines = questions.map((question, index) => {
        const selected =
            answers[index] ??
            answers[String(index)] ??
            '';

        if (!selected) {
            return `Câu ${index + 1}: Chưa chọn` +
                (
                    question?.correct
                        ? ` (Đúng là ${question.correct})`
                        : ''
                );
        }

        const isCorrect =
            question?.correct &&
            String(selected) ===
                String(question.correct);

        if (isCorrect) score++;

        return `Câu ${index + 1}: Chọn ${selected} ` +
            (
                question?.correct
                    ? (
                        isCorrect
                            ? '✅'
                            : `❌ (Đúng là ${question.correct})`
                    )
                    : ''
            );
    });

    if (assignment?.assessmentType === 'trac_nghiem') {
        const scale10 =
            Math.round(
                (score / questions.length) * 100
            ) / 10;

        lines.push(
            '',
            `=> 🎯 CHẤM ĐIỂM TỰ ĐỘNG: ${score} / ${questions.length} (Đạt ${scale10} / 10 điểm)`
        );
    } else {
        const weight = Number(
            assignment?.mcWeight ?? 5
        );

        const weightedScore =
            Math.round(
                (score / questions.length) *
                weight *
                100
            ) / 100;

        lines.push(
            '',
            `=> 🎯 CHẤM TỰ ĐỘNG PHẦN TRẮC NGHIỆM: ${score} / ${questions.length} (Đạt ${weightedScore} / ${weight} điểm)`
        );
    }

    return lines.join('\n');
}

function getStudentStoredEssayText(submission) {
    const rawEssay =
        typeof submission?.rawEssay === 'string'
            ? submission.rawEssay
            : '';

    if (rawEssay.trim()) {
        return rawEssay;
    }

    const existingAnswer = String(
        submission?.answer ||
        ''
    );

    const essayMarker = '[PHẦN TỰ LUẬN]';
    const markerIndex = existingAnswer.indexOf(
        essayMarker
    );

    if (markerIndex >= 0) {
        return existingAnswer
            .slice(markerIndex + essayMarker.length)
            .replace(/^\s+/, '');
    }

    // Bài tự luận cũ có thể chỉ lưu answer mà chưa có rawEssay/marker.
    if (
        existingAnswer &&
        !existingAnswer.includes('[PHẦN TRẮC NGHIỆM]')
    ) {
        return existingAnswer;
    }

    return '';
}

function getStudentAssignmentDescHTML(value) {
    const normalized = String(value || '')
        .replace(
            /\bql-align-(center|right|justify)\b/gi,
            ''
        )
        .replace(
            /text-align\s*:\s*(center|right|justify)\s*;?/gi,
            'text-align: left;'
        );

    return window.sanitizeRichHTML(
        normalized
    );
}

/*
 * Chuẩn hóa ID để tránh lỗi:
 * 123 !== "123"
 */
function normalizeStoreItemId(value) {
    return value === null || value === undefined
        ? ''
        : String(value);
}

/*
 * Vật phẩm thực sự mua bằng Coin:
 * giá phải là số và lớn hơn 0.
 */
function isCoinPurchasableStoreItem(item) {
    if (!item) return false;

    if (
        String(item.currency || '') ===
            'mid_autumn_coin' ||
        Number(item.midAutumnCoinCost || 0) > 0
    ) {
        return false;
    }

    const price = Number(item.price);

    return Number.isFinite(price) && price > 0;
}

/*
 * Kiểm tra vật phẩm có thuộc Cửa hàng Sang trọng hay không.
 */
function isLuxuryStoreItem(item) {
    if (!item) {
        return false;
    }

    // Ưu tiên cờ được gắn trực tiếp trên vật phẩm.
    if (item.luxuryOnly === true) {
        return true;
    }

    // Kiểm tra thêm theo danh sách ID của Luxury Store.
    if (
        window.LuxuryStore &&
        typeof window.LuxuryStore.isLuxuryItem === 'function'
    ) {
        return window.LuxuryStore.isLuxuryItem(item);
    }

    return false;
}

/*
 * Kiểm tra thẻ giảm giá áp dụng cho vật phẩm.
 */
function isDiscountEligibleForStoreItem(
    targetItems,
    item,
    discount = null
) {
    // Mọi thẻ chỉ áp dụng cho vật phẩm có giá Coin lớn hơn 0.
    if (!isCoinPurchasableStoreItem(item)) {
        return false;
    }

    // =====================================================
    // CỬA HÀNG SANG TRỌNG
    // Không cho sử dụng mã giảm giá thông thường.
    // =====================================================
    const isLuxuryItem =
        isLuxuryStoreItem(item);

    /*
     * Chừa sẵn khả năng tạo thẻ Luxury riêng sau này.
     *
     * Muốn một mã được dùng cho Luxury:
     * luxuryEligible: true
     *
     * hoặc:
     * discountScope: 'luxury'
     */
    const isLuxuryDiscount =
        discount?.luxuryEligible === true ||
        String(
            discount?.discountScope || ''
        ).toLowerCase() === 'luxury';

    if (
        isLuxuryItem &&
        !isLuxuryDiscount
    ) {
        return false;
    }

    const discountSource =
        discount?.source || 'teacher_gift';

    const isDailyLoginDiscount =
        discountSource === 'daily_login';

    const isTeacherGiftDiscount =
        discountSource === 'teacher_gift';

    const isHoiHoaRunnerUpDiscount =
        discountSource === 'hoihoa_runner_up' ||
        discountSource === 'hoihoa_season';

    const isHoiHoaChestDiscount =
        discountSource === 'hoihoa_chest';

    const itemPrice = Number(item.price);

    /*
     * Chuẩn hóa tag để nhận đúng:
     * Doraemon, doraemon, Truyền thuyết,
     * truyen thuyet...
     */
    const normalizeDiscountTag = value => {
        return String(value || '')
            .normalize('NFD')
            .replace(/[\u0300-\u036f]/g, '')
            .replace(/đ/g, 'd')
            .replace(/Đ/g, 'D')
            .trim()
            .toLowerCase();
    };

    const itemTags = [
        item.tag,
        ...(Array.isArray(item.tags) ? item.tags : [])
    ].map(normalizeDiscountTag);

    const hasBlockedHoiHoaTag =
        itemTags.includes('doraemon') ||
        itemTags.includes('truyen thuyet');

    if (
        isDailyLoginDiscount &&
        (
            !Number.isFinite(itemPrice) ||
            itemPrice > 500 ||
            item.isNonCoin === true ||
            hasBlockedHoiHoaTag
        )
    ) {
        return false;
    }

    // Thẻ giáo viên: món dưới 700 Coin.
    if (
        isTeacherGiftDiscount &&
        (
            !Number.isFinite(itemPrice) ||
            itemPrice >= 700
        )
    ) {
        return false;
    }

    /*
     * Thẻ Á quân Hội Họa:
     * - Chỉ vật phẩm bán bằng Coin.
     * - Không dùng cho vật phẩm sự kiện.
     * - Không dùng cho Doraemon/Truyền thuyết.
     * - Giá dưới 600 Coin.
     */
    if (
        isHoiHoaRunnerUpDiscount &&
        (
            !Number.isFinite(itemPrice) ||
            itemPrice >= 600 ||
            item.isNonCoin === true ||
            hasBlockedHoiHoaTag
        )
    ) {
        return false;
    }

    /*
     * Thẻ từ Rương Hội Họa:
     * - Chỉ vật phẩm bán bằng Coin.
     * - Không dùng cho vật phẩm sự kiện.
     * - Không dùng cho Doraemon/Truyền thuyết.
     * - Giá dưới 700 Coin.
     */
    if (
        isHoiHoaChestDiscount &&
        (
            !Number.isFinite(itemPrice) ||
            itemPrice >= 700 ||
            item.isNonCoin === true ||
            hasBlockedHoiHoaTag
        )
    ) {
        return false;
    }

    let normalizedTargets =
        targetItems || ['all'];

    if (!Array.isArray(normalizedTargets)) {
        normalizedTargets = [normalizedTargets];
    }

    normalizedTargets = normalizedTargets.map(
        normalizeStoreItemId
    );

    const itemId =
        normalizeStoreItemId(item.id);

    return (
        normalizedTargets.includes('all') ||
        normalizedTargets.includes(itemId)
    );
}

