// ECONOMY TRANSACTION HELPERS - CHỐNG RACE CONDITION NHIỀU TAB
// ==============================================================

async function incrementNumberTx(path, amount) {
    const ref = db.ref(path);

    const result = await ref.transaction(current => {
        const value = Number(current) || 0;
        return value + amount;
    });

    if (!result.committed) {
        throw new Error('TRANSACTION_NOT_COMMITTED');
    }

    return result.snapshot.val();
}

async function decrementNumberTx(path, amount) {
    const ref = db.ref(path);
    let reason = '';

    const result = await ref.transaction(current => {
        const value = Number(current) || 0;

        if (value < amount) {
            reason = 'INSUFFICIENT_BALANCE';
            return; // abort transaction
        }

        return value - amount;
    });

    if (!result.committed) {
        throw new Error(reason || 'TRANSACTION_NOT_COMMITTED');
    }

    return result.snapshot.val();
}

async function rollbackIncrement(path, amount) {
    try {
        await incrementNumberTx(path, amount);
    } catch (e) {
        console.warn('⚠️ Rollback cộng lại thất bại:', path, amount, e);
    }
}

async function rollbackDecrement(path, amount) {
    try {
        await decrementNumberTx(path, amount);
    } catch (e) {
        console.warn('⚠️ Rollback trừ lại thất bại:', path, amount, e);
    }
}

async function getActiveGradeRewardCoinExposureSnapshot(username) {
    const normalizedUsername = String(username || '').trim();
    if (!normalizedUsername) return {};

    try {
        const snap = await db
            .ref(`grade_reward_claims/${normalizedUsername}`)
            .once('value');

        const exposure = {};

        snap.forEach(child => {
            const claim = child.val() || {};
            const coins = Number(claim.coins || 0);
            const status = String(claim.status || '');

            if (
                status === 'claimed' &&
                coins > 0 &&
                !claim.reversedAt
            ) {
                exposure[String(child.key)] = {
                    coins,
                    claimedAt: Number(claim.claimedAt || 0),
                    rewardRevision: Number(claim.rewardRevision || 0),
                    submissionKey: String(claim.submissionKey || '')
                };
            }
        });

        return exposure;
    } catch (error) {
        console.warn(
            '[Grade Reward V4.3] Không đọc được snapshot claim Coin trước khi mua:',
            error
        );
        return {};
    }
}
