function getUsableSpecialBirthdayCoinCount(
    grants,
    now = Date.now()
) {
    return Object.values(grants || {})
        .reduce((total, grant) => {
            if (
                !grant ||
                typeof grant !== 'object'
            ) {
                return total;
            }

            const remaining =
                Number(
                    grant.remaining
                ) || 0;

            const expiresAt =
                Number(
                    grant.expiresAt
                ) || 0;

            if (
                remaining <= 0 ||
                !expiresAt ||
                now >= expiresAt
            ) {
                return total;
            }

            return total + remaining;
        }, 0);
}

window
    .getUsableSpecialBirthdayCoinCount =
    getUsableSpecialBirthdayCoinCount;

function getBirthdayCoinBalance(entry) {
    if (typeof entry === 'number') {
        return Number.isFinite(entry)
            ? entry
            : 0;
    }

    if (
        entry &&
        typeof entry === 'object'
    ) {
        const balance =
            Number(entry.balance);

        return Number.isFinite(balance)
            ? balance
            : 0;
    }

    return 0;
}

function normalizeBirthdayCoinBalances(wallets) {
    const balances = {};

    Object.entries(wallets || {})
        .forEach(([year, entry]) => {
            balances[String(year)] =
                getBirthdayCoinBalance(entry);
        });

    return balances;
}

