function getCurrentStudentBirthdayProfile() {
    const profile =
        currentUser?.birthdayProfile;

    if (
        profile &&
        typeof profile === 'object'
    ) {
        return profile;
    }

    // Hỗ trợ dữ liệu cũ.
    if (currentUser?.birthDate) {
        return {
            date: String(
                currentUser.birthDate
            ),
            enteredBy: 'legacy'
        };
    }

    return null;
}

function isValidBirthdayDateInput(value) {
    const text =
        String(value || '').trim();

    if (
        !/^\d{4}-\d{2}-\d{2}$/.test(text)
    ) {
        return false;
    }

    const [year, month, day] =
        text.split('-').map(Number);

    const date =
        new Date(year, month - 1, day);

    if (
        date.getFullYear() !== year ||
        date.getMonth() !== month - 1 ||
        date.getDate() !== day
    ) {
        return false;
    }

    const today = new Date();
    today.setHours(23, 59, 59, 999);

    return (
        year >= 1900 &&
        date.getTime() <= today.getTime()
    );
}

function formatBirthdayDateVN(value) {
    if (
        !isValidBirthdayDateInput(value)
    ) {
        return 'Chưa cập nhật';
    }

    const [year, month, day] =
        value.split('-');

    return `${day}/${month}/${year}`;
}

window.renderStudentBirthdayProfile =
    function () {
        const profile =
            getCurrentStudentBirthdayProfile();

        const display =
            document.getElementById(
                'infoModalBirthDate'
            );

        const inputArea =
            document.getElementById(
                'studentBirthDateInputArea'
            );

        const input =
            document.getElementById(
                'studentBirthDateInput'
            );

        const saveButton =
            document.getElementById(
                'saveStudentBirthDateBtn'
            );

        const note =
            document.getElementById(
                'studentBirthDateNote'
            );

        if (
            !display ||
            !inputArea ||
            !input ||
            !saveButton
        ) {
            return;
        }

        input.max =
            new Date()
                .toISOString()
                .slice(0, 10);

        if (
            profile &&
            isValidBirthdayDateInput(
                profile.date
            )
        ) {
            display.style.display = 'block';

            display.textContent =
                `${formatBirthdayDateVN(profile.date)} · ` +
                'Đã khóa chỉnh sửa phía học sinh';

            inputArea.style.display = 'none';
            input.disabled = true;
            saveButton.disabled = true;
        } else {
            display.style.display = 'none';
            inputArea.style.display = 'block';
            input.disabled = false;
            saveButton.disabled = false;
            input.value = '';

            if (note) {
                note.textContent =
                    'Lưu ý: học sinh chỉ được tự nhập ' +
                    'ngày sinh 1 lần duy nhất. ' +
                    'Hãy kiểm tra thật kỹ trước khi lưu.';
            }
        }
    };

window.saveStudentBirthDateOnce =
    async function () {
        if (currentUser.isLocked) {
            return alert(
                '🔒 Tài khoản đang bị khóa!'
            );
        }

        if (
            getCurrentStudentBirthdayProfile()
        ) {
            window
                .renderStudentBirthdayProfile();

            return alert(
                '🎂 Ngày sinh đã được lưu trước đó. ' +
                'Học sinh không thể sửa lại.'
            );
        }

        const input =
            document.getElementById(
                'studentBirthDateInput'
            );

        const saveButton =
            document.getElementById(
                'saveStudentBirthDateBtn'
            );

        const birthDate =
            String(input?.value || '').trim();

        if (
            !isValidBirthdayDateInput(
                birthDate
            )
        ) {
            return alert(
                '🎂 Ngày sinh không hợp lệ, ' +
                'nằm trong tương lai hoặc trước năm 1900!'
            );
        }

        const formatted =
            formatBirthdayDateVN(birthDate);

        if (
            !confirm(
                `Bạn xác nhận ngày sinh là ${formatted}?\n\n` +
                'Học sinh chỉ được tự nhập đúng 1 lần ' +
                'và không thể sửa lại.'
            )
        ) {
            return;
        }

        if (saveButton) {
            saveButton.disabled = true;
            saveButton.textContent =
                '⏳ Đang lưu...';
        }

        try {
            const uid =
                firebase.auth().currentUser?.uid ||
                currentUser._fbKey;

            if (!uid) {
                throw new Error(
                    'Không xác định được UID học sinh.'
                );
            }

            const profileRef = db.ref(
                `users/${uid}/birthdayProfile`
            );

            const transaction =
                await profileRef.transaction(
                    current => {
                        // Đã tồn tại thì hủy.
                        if (current !== null) {
                            return;
                        }

                        return {
                            date: birthDate,
                            enteredBy: 'student',
                            enteredAt:
                                firebase.database
                                    .ServerValue
                                    .TIMESTAMP
                        };
                    }
                );

            if (!transaction.committed) {
                throw new Error(
                    'BIRTHDAY_ALREADY_EXISTS'
                );
            }

            currentUser.birthdayProfile =
                transaction.snapshot.val() || {
                    date: birthDate,
                    enteredBy: 'student',
                    enteredAt: Date.now()
                };

            localStorage.setItem(
                'currentUser',
                JSON.stringify(Object.fromEntries(Object.entries(currentUser).filter(([key]) => !['password', 'newPass', 'oldPass'].includes(key))))
            );

            window
                .renderStudentBirthdayProfile();

            alert(
                `✅ Đã lưu ngày sinh ${formatted}.\n` +
                'Đến đúng ngày sinh, hệ thống sẽ gửi ' +
                '1 Xu Sinh Nhật của năm đó qua Hộp thư.'
            );
        } catch (error) {
            console.error(
                'Lỗi lưu ngày sinh:',
                error
            );

            if (
                error.message ===
                'BIRTHDAY_ALREADY_EXISTS' ||
                error.code ===
                'PERMISSION_DENIED'
            ) {
                alert(
                    '🎂 Ngày sinh đã được lưu trước đó ' +
                    'hoặc tài khoản không còn quyền tự sửa.'
                );
            } else {
                alert(
                    '❌ Không lưu được ngày sinh: ' +
                    (
                        error.message ||
                        'lỗi không xác định'
                    )
                );
            }
        } finally {
            if (
                saveButton &&
                !getCurrentStudentBirthdayProfile()
            ) {
                saveButton.disabled = false;
                saveButton.textContent =
                    '🎁 Lưu ngày sinh';
            }
        }
    };

window.openStudentInfoModal = function () {
    if (window.currentActiveExamId) {
        window.showExamLockWarning(
            "⚠️ Hồ sơ cá nhân tạm khóa khi thi!"
        );
        return;
    }

    const modal = document.getElementById(
        "studentInfoModal"
    );

    const avatarPreview = document.getElementById(
        "modalAvatarPreview"
    );

    const saveAvatarBtn = document.getElementById(
        "saveAvatarBtn"
    );

    const nameElement = document.getElementById(
        "infoModalName"
    );

    const classElement = document.getElementById(
        "infoModalClass"
    );

    const hobbiesElement = document.getElementById(
        "infoModalHobbies"
    );

    const mottoElement = document.getElementById(
        "infoModalMotto"
    );

    if (
        !modal ||
        !avatarPreview ||
        !saveAvatarBtn
    ) {
        console.error(
            "Không tìm thấy giao diện hồ sơ học sinh."
        );
        return;
    }

    /*
     * Avatar mặc định có biểu tượng người dùng.
     * Không dùng ảnh PNG trong suốt 1x1 nữa.
     */
    const defaultAvatarSVG = `
        <svg
            xmlns="http://www.w3.org/2000/svg"
            width="200"
            height="200"
            viewBox="0 0 200 200"
        >
            <defs>
                <linearGradient
                    id="avatarBackground"
                    x1="0"
                    y1="0"
                    x2="1"
                    y2="1"
                >
                    <stop
                        offset="0%"
                        stop-color="#eef2ff"
                    />

                    <stop
                        offset="100%"
                        stop-color="#ede9fe"
                    />
                </linearGradient>
            </defs>

            <rect
                width="200"
                height="200"
                rx="100"
                fill="url(#avatarBackground)"
            />

            <circle
                cx="100"
                cy="73"
                r="34"
                fill="#818cf8"
            />

            <path
                d="M42 172c5-38 27-57 58-57s53 19 58 57"
                fill="#818cf8"
            />
        </svg>
    `;

    const defaultAvatar =
        "data:image/svg+xml;charset=UTF-8," +
        encodeURIComponent(defaultAvatarSVG);

    const savedAvatar =
        typeof currentUser.avatar === "string"
            ? currentUser.avatar.trim()
            : "";

    const hasValidAvatar =
        savedAvatar.startsWith("data:image/") ||
        savedAvatar.startsWith("https://") ||
        savedAvatar.startsWith("http://") ||
        savedAvatar.startsWith("blob:");

    avatarPreview.src =
        hasValidAvatar
            ? savedAvatar
            : defaultAvatar;

    avatarPreview.onerror = function () {
        this.onerror = null;
        this.src = defaultAvatar;
    };

    saveAvatarBtn.style.display = "none";

    if (nameElement) {
        nameElement.textContent =
            currentUser.name ||
            "Chưa cập nhật";
    }

    if (classElement) {
        classElement.textContent =
            "Lớp: " +
            (
                currentUser.classInfo ||
                "Chưa cập nhật"
            );
    }

    if (hobbiesElement) {
        hobbiesElement.textContent =
            currentUser.hobbies ||
            "Chưa cập nhật";
    }

    if (mottoElement) {
        mottoElement.textContent =
            currentUser.motto ||
            "Chưa cập nhật";
    }

    window.renderStudentBirthdayProfile();
    modal.classList.add("active");
};

window.closeStudentInfoModal = function () {
    document.getElementById('studentInfoModal').classList.remove('active');
};

// ==============================================================
// HỆ THỐNG XỬ LÝ ẢNH ĐẠI DIỆN (AVATAR)
// ==============================================================

// 1. Hàm hiển thị ảnh đại diện lên góc màn hình ngay khi đăng nhập
function studentProfileButtonHasFrame(triggerBtn) {
    if (!triggerBtn) return false;

    return (
        triggerBtn.classList.contains('avatar-frame-equipped') ||
        triggerBtn.hasAttribute('data-avatar-frame-id') ||
        triggerBtn.hasAttribute('data-avatar-frame-effect')
    );
}

function applyStudentProfileButtonBaseVisual(triggerBtn) {
    if (!triggerBtn || studentProfileButtonHasFrame(triggerBtn)) return false;

    /*
     * PROFILE CIRCLE FIX v2
     * Nút Hồ sơ vốn là avatar tròn, KHÔNG phải một action-card vuông bo 14px.
     * Giữ host là hình vuông 1:1 để ảnh không bao giờ bị ép thành oval,
     * còn kích thước 40/44px vẫn do top-actions quyết định để không tái phát
     * lỗi nút kéo dài toàn hàng.
     */
    [
        ['overflow', 'hidden'],
        ['border-radius', '50%'],
        ['background', 'rgba(255,255,255,.78)'],
        ['border', '1px solid rgba(255,255,255,.92)'],
        ['box-shadow', '0 8px 22px rgba(15,23,42,.10)'],
        ['isolation', 'isolate'],
        ['z-index', '1'],
        ['display', 'grid'],
        ['place-items', 'center'],
        ['aspect-ratio', '1 / 1']
    ].forEach(([property, value]) => {
        triggerBtn.style.setProperty(property, value, 'important');
    });

    triggerBtn.style.setProperty('backdrop-filter', 'blur(12px)');
    triggerBtn.style.setProperty('-webkit-backdrop-filter', 'blur(12px)');

    const avatarImg = triggerBtn.querySelector('#avatarImage');
    if (avatarImg) {
        const size = window.matchMedia('(max-width: 768px)').matches
            ? '38px'
            : '42px';

        [
            ['display', 'block'],
            ['width', size],
            ['height', size],
            ['min-width', size],
            ['min-height', size],
            ['max-width', size],
            ['max-height', size],
            ['flex', `0 0 ${size}`],
            ['aspect-ratio', '1 / 1'],
            ['box-sizing', 'border-box'],
            ['object-fit', 'cover'],
            ['object-position', 'center center'],
            ['border-radius', '50%'],
            ['position', 'relative'],
            ['inset', 'auto'],
            ['transform', 'none']
        ].forEach(([property, value]) => {
            avatarImg.style.setProperty(property, value, 'important');
        });
    }

    const avatarPlaceholder = triggerBtn.querySelector('#avatarPlaceholder');
    if (avatarPlaceholder) {
        avatarPlaceholder.style.setProperty('border-radius', '50%', 'important');
        avatarPlaceholder.style.setProperty('place-items', 'center', 'important');
    }

    return true;
}

function releaseStudentProfileButtonBaseVisualForFrame(triggerBtn) {
    if (!triggerBtn) return;

    // Khi bắt đầu đeo khung, trả quyền kích thước avatar về CSS riêng của frame.
    const avatarImg = triggerBtn.querySelector('#avatarImage');
    if (avatarImg) {
        [
            'width',
            'height',
            'min-width',
            'min-height',
            'max-width',
            'max-height',
            'position',
            'inset',
            'transform'
        ].forEach(property => {
            avatarImg.style.removeProperty(property);
        });

        // Fallback giống HTML gốc; CSS riêng của frame dùng !important vẫn có
        // thể ghi đè kích thước này khi cần.
        avatarImg.style.setProperty('width', '100%');
        avatarImg.style.setProperty('height', '100%');
        avatarImg.style.setProperty('object-fit', 'cover');
        avatarImg.style.setProperty('border-radius', '50%');
    }

    triggerBtn.style.setProperty('background', 'transparent', 'important');
    triggerBtn.style.setProperty('border', '0 solid transparent', 'important');
    triggerBtn.style.setProperty('box-shadow', 'none', 'important');
    triggerBtn.style.setProperty('overflow', 'visible', 'important');
    triggerBtn.style.setProperty('border-radius', '50%', 'important');
    triggerBtn.style.setProperty('isolation', 'isolate', 'important');
    triggerBtn.style.setProperty('z-index', '4', 'important');
}

function clearStudentProfileButtonFrameResidue(triggerBtn) {
    if (!triggerBtn) return;

    triggerBtn.removeAttribute('data-avatar-frame-id');
    triggerBtn.removeAttribute('data-avatar-frame-effect');

    Array.from(triggerBtn.classList).forEach(className => {
        if (
            className === 'avatar-frame-equipped' ||
            className === 'avatar-frame-profile-host' ||
            className === 'avatar-frame-viet-dieu-host' ||
            /(?:^|-)frame-host$/.test(className)
        ) {
            triggerBtn.classList.remove(className);
        }
    });

    triggerBtn.querySelectorAll(
        ':scope > .avatar-frame-decoration,' +
        ':scope > .avatar-frame-aura,' +
        ':scope > .avatar-frame-spark,' +
        ':scope > [class*="-frame-decoration"],' +
        ':scope > [class*="-frame-aura"],' +
        ':scope > [class*="-frame-rune"],' +
        ':scope > [class*="-frame-glint"]'
    ).forEach(node => node.remove());

    applyStudentProfileButtonBaseVisual(triggerBtn);
}

function updateAvatarDisplay(avatarData) {
    const avatarImg = document.getElementById('avatarImage');
    const avatarPlaceholder = document.getElementById('avatarPlaceholder');
    const triggerBtn = document.querySelector('.profile-trigger-btn');

    // Không để lỗi avatar làm gián đoạn phần còn lại của trang.
    if (!avatarImg || !avatarPlaceholder || !triggerBtn) return;

    const normalizedAvatar =
        typeof avatarData === 'string'
            ? avatarData.trim()
            : '';

    const hasValidAvatar =
        normalizedAvatar.startsWith('data:image') ||
        normalizedAvatar.startsWith('https://') ||
        normalizedAvatar.startsWith('http://') ||
        normalizedAvatar.startsWith('blob:');

    // Mỗi lần đổi avatar dùng một request id để ảnh cũ tải chậm không thể
    // ghi đè lên avatar mới hơn.
    const requestId = String(
        (Number(avatarImg.dataset.avatarRequestId) || 0) + 1
    );
    avatarImg.dataset.avatarRequestId = requestId;

    const showPlaceholder = () => {
        avatarImg.style.display = 'none';
        avatarPlaceholder.style.display = 'flex';
        triggerBtn.classList.remove('avatar-ready');

        if (!studentProfileButtonHasFrame(triggerBtn)) {
            applyStudentProfileButtonBaseVisual(triggerBtn);
        }
    };

    const showAvatar = () => {
        if (avatarImg.dataset.avatarRequestId !== requestId) return;
        if (!avatarImg.complete || avatarImg.naturalWidth <= 0) return;

        avatarImg.style.display = 'block';
        avatarPlaceholder.style.display = 'none';
        triggerBtn.classList.add('avatar-ready');

        /*
         * Không còn biến nút Hồ sơ thành transparent chỉ vì có avatar.
         * Transparent chỉ dành cho trạng thái đang đeo KHUNG.
         */
        if (!studentProfileButtonHasFrame(triggerBtn)) {
            applyStudentProfileButtonBaseVisual(triggerBtn);
        }
    };

    // Quan trọng: nút hồ sơ + biểu tượng 👤 luôn hiện NGAY. Chỉ thay bằng ảnh
    // sau khi ảnh đã tải thành công, tránh khoảng trống trong lúc mạng chậm.
    showPlaceholder();

    if (!hasValidAvatar) {
        avatarImg.onload = null;
        avatarImg.onerror = null;
        avatarImg.removeAttribute('src');
        return;
    }

    avatarImg.loading = 'eager';
    avatarImg.decoding = 'async';
    try {
        avatarImg.fetchPriority = 'high';
    } catch (_) { }

    avatarImg.onload = showAvatar;
    avatarImg.onerror = () => {
        if (avatarImg.dataset.avatarRequestId !== requestId) return;
        showPlaceholder();
    };

    // Nếu cùng URL đã nằm trong cache trình duyệt thì hiện ngay, không tạo
    // một request mạng thừa. Nếu chưa có, gán src để bắt đầu tải.
    const currentSrc = avatarImg.getAttribute('src') || '';
    if (currentSrc !== normalizedAvatar) {
        avatarImg.src = normalizedAvatar;
    }

    if (avatarImg.complete && avatarImg.naturalWidth > 0) {
        showAvatar();
    }
}

// 2. Chức năng xem trước ảnh khi học sinh chọn file
let selectedAvatarFile = null;
let selectedAvatarPreviewUrl = '';

window.previewAvatar = function (input) {
    if (
        !input.files ||
        !input.files[0]
    ) {
        return;
    }

    const file =
        input.files[0];

    if (
        !file.type.startsWith(
            'image/'
        )
    ) {
        alert(
            'Vui lòng chọn đúng file ảnh!'
        );

        input.value = '';

        return;
    }

    if (
        file.size >
        1024 * 1024
    ) {
        alert(
            'Ảnh quá lớn! ' +
            'Vui lòng chọn ảnh nhỏ hơn 1 MB.'
        );

        input.value = '';

        return;
    }

    if (selectedAvatarPreviewUrl) {
        URL.revokeObjectURL(
            selectedAvatarPreviewUrl
        );
    }

    /*
     * URL tạm chỉ dùng để xem trước.
     * Không lưu URL blob vào Firebase.
     */
    selectedAvatarPreviewUrl =
        URL.createObjectURL(file);

    selectedAvatarFile =
        file;

    const preview =
        document.getElementById(
            'modalAvatarPreview'
        );

    if (preview) {
        preview.src =
            selectedAvatarPreviewUrl;
    }

    const saveButton =
        document.getElementById(
            'saveAvatarBtn'
        );

    if (saveButton) {
        saveButton.style.display =
            'block';
    }
};

window.saveNewAvatar = async function () {
    if (!selectedAvatarFile) {
        return;
    }

    const cornerImg =
        document.getElementById(
            'avatarImage'
        );

    if (cornerImg) {
        cornerImg.classList.add(
            'loading'
        );
    }

    try {
        const uploaded =
            await window
                .CloudinaryStorage
                .uploadFile(
                    selectedAvatarFile,
                    {
                        maxSizeBytes:
                            1024 * 1024
                    }
                );

        /*
         * Chỉ lưu URL, không lưu Base64.
         */
        const userKey =
            firebase.auth().currentUser?.uid ||
            currentUser._fbKey;

        if (!userKey) {
            throw new Error(
                'Không xác định được UID học sinh.'
            );
        }

        const avatarUpdates = {};

        avatarUpdates[
            `users/${userKey}/avatar`
        ] = uploaded.url;

        avatarUpdates[
            `users/${userKey}/avatarStorage`
        ] = uploaded;

        await db.ref().update(avatarUpdates);

        currentUser.avatar =
            uploaded.url;

        currentUser.avatarStorage =
            uploaded;

        localStorage.setItem(
            'currentUser',
            JSON.stringify(
                currentUser
            )
        );

        updateAvatarDisplay(
            uploaded.url
        );

        const saveButton =
            document.getElementById(
                'saveAvatarBtn'
            );

        if (saveButton) {
            saveButton.style.display =
                'none';
        }

        selectedAvatarFile = null;

        if (
            selectedAvatarPreviewUrl
        ) {
            URL.revokeObjectURL(
                selectedAvatarPreviewUrl
            );

            selectedAvatarPreviewUrl =
                '';
        }

        alert(
            'Đã cập nhật ảnh đại diện thành công! 🎉'
        );
    } catch (error) {
        console.error(error);

        alert(
            `❌ Không tải được ảnh đại diện: ` +
            `${error.message}`
        );
    } finally {
        if (cornerImg) {
            cornerImg.classList.remove(
                'loading'
            );
        }
    }
};

