window.isMobileExamEnvironment = function () {
    /*
     * V5: chỉ dùng cho UI/khả năng tương thích.
     * TUYỆT ĐỐI không dùng UA/mobile detection để miễn vi phạm.
     * User-Agent có thể bị giả bằng DevTools.
     */
    const userAgent = String(
        navigator.userAgent || ''
    );

    const userAgentDataMobile =
        navigator.userAgentData?.mobile === true;

    const mobileUserAgent =
        /Android|iPhone|iPad|iPod|Mobile|Zalo/i.test(
            userAgent
        );

    const isIPadOS =
        navigator.platform === 'MacIntel' &&
        Number(
            navigator.maxTouchPoints || 0
        ) > 1;

    return Boolean(
        userAgentDataMobile ||
        mobileUserAgent ||
        isIPadOS
    );
};


// Ngăn blur và fullscreenchange của cùng một sự cố
// bị hệ thống đếm thành hai lần khác nhau.
window.examInterruptionGuard = {
    lastExamId: '',
    lastAt: 0,
    windowMs: 2500,

    isDuplicate(assignId) {
        const now = Date.now();
        const examId = String(assignId || '');

        const duplicated =
            this.lastExamId === examId &&
            now - this.lastAt < this.windowMs;

        if (!duplicated) {
            this.lastExamId = examId;
            this.lastAt = now;
        }

        return duplicated;
    }
};


// Điện thoại/Zalo chỉ lưu trạng thái gián đoạn,
// không tăng interruptionCount.
window.recordSoftExamInterruption = async function (
    assignId,
    reason
) {
    const manager =
        window.examRecoveryManager;

    const authoritative =
        await manager
            .readAuthoritativeSession(
                assignId
            );

    const interruptionCount =
        Number(
            authoritative
                ?.interruptionCount ||
            0
        );

    await manager.sync(
        assignId,
        {
            status: 'interrupted',
            interruptionCount,
            lastReason:
                `soft-${reason}`
        }
    );

    return interruptionCount;
};


