window.updateVideoSummaryAccess =
    function (
        assignId,
        isUnlocked,
        requiredSeconds = 0
    ) {
        // Nút trượt ngang trên máy tính.
        const desktopButton =
            document.getElementById(
                `video-summary-toggle-${assignId}`
            );

        // Nút xổ xuống trên điện thoại.
        const mobileButton =
            document.getElementById(
                `video-summary-mobile-toggle-${assignId}`
            );

        const buttons = [
            desktopButton,
            mobileButton
        ].filter(Boolean);

        const note =
            document.getElementById(
                `video-summary-lock-note-${assignId}`
            );

        if (buttons.length === 0) {
            return;
        }

        buttons.forEach(button => {
            button.dataset.requiredSeconds =
                String(
                    Number(
                        requiredSeconds
                    ) || 0
                );

            button.disabled =
                !isUnlocked;

            button.classList.toggle(
                'is-locked',
                !isUnlocked
            );

            button.title =
                isUnlocked
                    ? 'Mở bảng tóm tắt'
                    : (
                        'Cần đạt điều kiện ' +
                        'xem video trước'
                    );
        });

        if (note) {
            note.classList.toggle(
                'show',
                !isUnlocked
            );

            note.textContent =
                isUnlocked
                    ? ''
                    : (
                        '🔒 Bảng tóm tắt sẽ mở ' +
                        'sau khi đạt điều kiện ' +
                        'xem video.'
                    );
        }
    };

window.startVideoSummaryResize =
    function (event, assignId) {
        // Chỉ nhận chuột trái.
        if (
            event.button !== undefined &&
            event.button !== 0
        ) {
            return;
        }

        event.preventDefault();
        event.stopPropagation();

        const shell =
            document.getElementById(
                `tracked-video-shell-${assignId}`
            );

        const panel =
            document.getElementById(
                `video-summary-panel-${assignId}`
            );

        const handle =
            event.currentTarget;

        if (
            !shell ||
            !panel ||
            !handle
        ) {
            return;
        }

        const pointerId =
            event.pointerId;

        document.body.classList.add(
            'video-summary-resizing'
        );

        shell.classList.add(
            'is-resizing'
        );

        /*
        Giữ sự kiện chuột ở thanh kéo.
        Dù con trỏ đi qua iframe YouTube,
        thao tác kéo vẫn không bị mất.
        */
        try {
            handle.setPointerCapture(
                pointerId
            );
        } catch (error) {
            // Trình duyệt không hỗ trợ thì bỏ qua.
        }

        const updateWidth =
            clientX => {
                const rect =
                    shell.getBoundingClientRect();

                if (!rect.width) return;

                const rawPercent =
                    (
                        (
                            clientX -
                            rect.left
                        ) /
                        rect.width
                    ) * 100;

                const isMobile =
                    window.innerWidth <= 700;

                const minPercent =
                    isMobile ? 45 : 25;

                const maxPercent =
                    isMobile ? 94 : 90;

                const widthPercent =
                    Math.min(
                        maxPercent,
                        Math.max(
                            minPercent,
                            rawPercent
                        )
                    );

                shell.style.setProperty(
                    '--video-summary-width',
                    `${widthPercent}%`
                );
            };

        // Cập nhật ngay từ vị trí nhấn đầu tiên.
        updateWidth(
            event.clientX
        );

        const move =
            moveEvent => {
                if (
                    moveEvent.pointerId !==
                    pointerId
                ) {
                    return;
                }

                moveEvent.preventDefault();

                updateWidth(
                    moveEvent.clientX
                );
            };

        const cleanup = () => {
            window.removeEventListener(
                'pointermove',
                move
            );

            window.removeEventListener(
                'pointerup',
                stop
            );

            window.removeEventListener(
                'pointercancel',
                stop
            );

            window.removeEventListener(
                'blur',
                cleanup
            );

            document.body.classList.remove(
                'video-summary-resizing'
            );

            shell.classList.remove(
                'is-resizing'
            );

            try {
                if (
                    handle.hasPointerCapture(
                        pointerId
                    )
                ) {
                    handle.releasePointerCapture(
                        pointerId
                    );
                }
            } catch (error) {
                // Không cần xử lý.
            }
        };

        const stop =
            stopEvent => {
                if (
                    stopEvent.pointerId !==
                    pointerId
                ) {
                    return;
                }

                cleanup();
            };

        window.addEventListener(
            'pointermove',
            move,
            {
                passive: false
            }
        );

        window.addEventListener(
            'pointerup',
            stop
        );

        window.addEventListener(
            'pointercancel',
            stop
        );

        // Tránh bị kẹt trạng thái kéo khi đổi cửa sổ.
        window.addEventListener(
            'blur',
            cleanup,
            {
                once: true
            }
        );
    };

function updateVideoWatchDisplays(assignId, seconds) {
    const formattedTime =
        formatSecondsToDHMS(Number(seconds) || 0);

    // Dòng nằm dưới video
    const videoDisplay =
        document.getElementById(
            `watch-time-display-${assignId}`
        );

    // Dòng nằm trong bảng cảnh báo điều kiện
    const conditionDisplay =
        document.getElementById(
            `condition-watch-display-${assignId}`
        );

    if (videoDisplay) {
        videoDisplay.innerText = formattedTime;
    }

    if (conditionDisplay) {
        conditionDisplay.innerText = formattedTime;
    }
}

window.initYouTubeTrackers = function (
    assignments,
    retryCount = 0
) {
    bindVideoProgressFlushEvents();

    if (
        typeof YT === 'undefined' ||
        typeof YT.Player === 'undefined'
    ) {
        if (retryCount < 10) {
            setTimeout(
                () =>
                    window.initYouTubeTrackers(
                        assignments,
                        retryCount + 1
                    ),
                1000
            );
        }

        return;
    }

    const renderedPlayerIds = new Set();
    const assignmentMap = new Map(
        (assignments || []).map(assign => [
            String(assign.id),
            assign
        ])
    );

    const initializePlayer = (assign, iframeEl) => {
        if (!assign || !iframeEl || !iframeEl.isConnected) return;

        const assignId = String(assign.id);
        const existingPlayer = ytPlayers[assignId];

        if (existingPlayer) {
            let existingIframe = null;

            try {
                existingIframe =
                    typeof existingPlayer.getIframe === 'function'
                        ? existingPlayer.getIframe()
                        : null;
            } catch (error) {
                existingIframe = null;
            }

            if (existingIframe !== iframeEl) {
                destroyTrackedYouTubePlayer(assignId);
            }
        }

        if (ytPlayers[assignId]) return;

        videoTrackerReady[assignId] = false;

        ytPlayers[assignId] = new YT.Player(
            iframeEl.id,
            {
                events: {
                    onReady: event => {
                        const resumeEnabled =
                            iframeEl.dataset.resumePlayback !==
                            'false';

                        /*
                         * YouTube có thể ghi nhớ tốc độ từ lần
                         * xem trước. Luôn đưa player về 1× ngay
                         * khi sẵn sàng, nhưng chưa tua vị trí ở
                         * đây để cơ chế resume vẫn hoạt động.
                         */
                        enforceAssignmentVideoNormalSpeed(
                            assignId,
                            event.target,
                            false,
                            false
                        );

                        db.ref(
                            `video_tracking/${assignId}/${currentUser.username}`
                        )
                            .once('value')
                            .then(snap => {
                                const firebaseSeconds =
                                    normalizeVideoProgressSeconds(
                                        snap.val()
                                    );

                                const localSeconds =
                                    resumeEnabled
                                        ? getLocalVideoProgress(
                                            assignId
                                        )
                                        : 0;

                                watchDurations[
                                    assignId
                                ] = Math.max(
                                    firebaseSeconds,
                                    localSeconds,
                                    normalizeVideoProgressSeconds(
                                        watchDurations[
                                            assignId
                                        ]
                                    )
                                );

                                lastSavedTime[
                                    assignId
                                ] = firebaseSeconds;

                                updateVideoWatchDisplays(
                                    assignId,
                                    watchDurations[
                                        assignId
                                    ]
                                );

                                const requiredSeconds =
                                    Number(
                                        assign.watchCondition
                                    ) || 0;

                                window.updateVideoSummaryAccess(
                                    assignId,
                                    requiredSeconds <= 0 ||
                                    watchDurations[
                                        assignId
                                    ] >= requiredSeconds,
                                    requiredSeconds
                                );

                                if (
                                    resumeEnabled &&
                                    watchDurations[
                                        assignId
                                    ] > 0
                                ) {
                                    pendingResumeTimes[
                                        assignId
                                    ] =
                                        watchDurations[
                                            assignId
                                        ];

                                    setTimeout(
                                        () => {
                                            seekToSavedVideoProgress(
                                                assignId,
                                                event.target,
                                                false
                                            );
                                        },
                                        150
                                    );
                                }

                                /*
                                 * Nếu chưa có tiến độ hợp lệ, ép player về đầu.
                                 * YouTube đôi khi tự khôi phục vị trí phát từ
                                 * lịch sử/cookie và vị trí đó không được tính.
                                 */
                                if (
                                    watchDurations[
                                        assignId
                                    ] <= 0
                                ) {
                                    try {
                                        const bootTime =
                                            Number(
                                                event.target
                                                    .getCurrentTime?.()
                                            ) || 0;

                                        if (
                                            bootTime > 1 &&
                                            typeof event.target
                                                .seekTo === 'function'
                                        ) {
                                            event.target.seekTo(
                                                0,
                                                true
                                            );
                                        }
                                    } catch (error) {
                                        console.warn(
                                            'Không thể đưa video về đầu:',
                                            error
                                        );
                                    }
                                }

                                lastPlayerSamples[
                                    assignId
                                ] = {
                                    videoTime:
                                        Number(
                                            event.target
                                                .getCurrentTime?.()
                                        ) || 0,
                                    wallTime:
                                        Date.now()
                                };

                                videoTrackerReady[
                                    assignId
                                ] = true;

                                if (
                                    localSeconds >
                                    firebaseSeconds
                                ) {
                                    saveVideoProgressToFirebase(
                                        assignId,
                                        watchDurations[
                                            assignId
                                        ]
                                    );
                                }

                                /*
                                 * PLAYING có thể phát sinh trước khi Firebase
                                 * tải xong. Khi tracking sẵn sàng, khởi động lại
                                 * bộ đếm nếu video vẫn đang phát.
                                 */
                                setTimeout(() => {
                                    try {
                                        if (
                                            event.target
                                                .getPlayerState?.() ===
                                            YT.PlayerState.PLAYING
                                        ) {
                                            window.onPlayerStateChange(
                                                {
                                                    target:
                                                        event.target,
                                                    data:
                                                        YT.PlayerState.PLAYING
                                                },
                                                assignId
                                            );
                                        }
                                    } catch (error) {
                                        // Không chặn player nếu API chưa phản hồi.
                                    }
                                }, 180);
                            })
                            .catch(error => {
                                console.error(
                                    'Không thể tải tiến độ xem video:',
                                    error
                                );
                            });
                    },

                    onStateChange: event =>
                        window.onPlayerStateChange(
                            event,
                            assignId
                        ),

                    onPlaybackRateChange: event =>
                        window
                            .onAssignmentVideoPlaybackRateChange(
                                event,
                                assignId
                            )
                }
            }
        );
    };

    const lazyMode =
        isStudentPerformanceOptimizationEnabled() &&
        typeof IntersectionObserver !== 'undefined';

    if (window.__assignmentVideoLazyObserver) {
        window.__assignmentVideoLazyObserver.disconnect();
        window.__assignmentVideoLazyObserver = null;
    }

    const pending = [];

    (assignments || []).forEach(assign => {
        const assignId = String(assign.id);
        const iframeId = `yt-player-${assignId}`;
        const iframeEl =
            document.getElementById(iframeId);

        if (!iframeEl) return;

        renderedPlayerIds.add(assignId);

        if (lazyMode && !ytPlayers[assignId]) {
            pending.push(iframeEl);
        } else {
            initializePlayer(assign, iframeEl);
        }
    });

    if (lazyMode && pending.length) {
        window.__assignmentVideoLazyObserver =
            new IntersectionObserver(
                entries => {
                    entries.forEach(entry => {
                        if (!entry.isIntersecting) return;

                        const iframeEl = entry.target;
                        const assignId =
                            String(
                                iframeEl.dataset.assignmentId ||
                                iframeEl.id.replace(
                                    'yt-player-',
                                    ''
                                )
                            );

                        const assign =
                            assignmentMap.get(assignId);

                        window.__assignmentVideoLazyObserver
                            ?.unobserve(iframeEl);

                        initializePlayer(
                            assign,
                            iframeEl
                        );
                    });
                },
                {
                    root: null,
                    // Tải trước khoảng 900px để khi học sinh cuộn tới
                    // player thường đã bắt đầu sẵn sàng.
                    rootMargin: '900px 0px',
                    threshold: 0.01
                }
            );

        pending.forEach(iframeEl => {
            window.__assignmentVideoLazyObserver.observe(
                iframeEl
            );
        });
    }

    Object.keys(ytPlayers).forEach(
        assignId => {
            if (
                !renderedPlayerIds.has(
                    String(assignId)
                ) ||
                !document.getElementById(
                    `yt-player-${assignId}`
                )
            ) {
                destroyTrackedYouTubePlayer(
                    assignId
                );
            }
        }
    );
};

window.onPlayerStateChange = function (event, assignId) {
    const player = event.target; // Lấy trực tiếp video đang phát

    if (typeof MusicManager !== 'undefined') {
        MusicManager.handleYouTubeVideoState(
            `assignment-video:${assignId}`,
            event.data
        );
    }

    if (event.data === YT.PlayerState.PLAYING) {
        /*
         * Tốc độ của mọi video bài tập/bài thi luôn là 1×.
         * Việc này không ảnh hưởng nút fullscreen.
         */
        enforceAssignmentVideoNormalSpeed(
            assignId,
            player,
            false,
            false
        );

        /*
         * Không cho phát/tính thời gian khi học sinh đã chuyển
         * sang YouTube, tab khác hoặc cửa sổ khác.
         */
        if (!isAssignmentVideoPageActive()) {
            pauseTrackedVideoBecausePageInactive(
                assignId,
                player,
                'play-while-inactive'
            );
            return;
        }

        delete videoPausedByPageExit[assignId];

        /*
         * Không ghi nhận thời gian trước khi tiến độ Firebase
         * của assignment hiện tại đã tải xong.
         */
        if (videoTrackerReady[assignId] !== true) {
            if (watchTimers[assignId]) {
                clearInterval(
                    watchTimers[assignId]
                );

                delete watchTimers[
                    assignId
                ];
            }

            return;
        }

        seekToSavedVideoProgress(
            assignId,
            player,
            true
        );

        if (watchTimers[assignId]) {
            clearInterval(watchTimers[assignId]);
        }

        watchTimers[assignId] = setInterval(() => {
            /*
             * Lớp bảo vệ thứ hai: dù trình duyệt bỏ sót blur/
             * visibilitychange, tuyệt đối không cộng thời gian
             * khi trang học tập không còn hoạt động.
             */
            if (!isAssignmentVideoPageActive()) {
                pauseTrackedVideoBecausePageInactive(
                    assignId,
                    player,
                    'timer-inactive'
                );
                return;
            }

            if (player && typeof player.getCurrentTime === 'function') {
                /*
                 * Lớp bảo vệ liên tục: nếu menu/phím tắt/extension
                 * vừa đổi tốc độ, không ghi nhận tick này và hoàn
                 * tác về mốc hợp lệ.
                 */
                if (
                    !enforceAssignmentVideoNormalSpeed(
                        assignId,
                        player,
                        true,
                        true
                    )
                ) {
                    return;
                }

                const rawCurrentTime =
                    Number(player.getCurrentTime()) || 0;

                let currentTime =
                    Math.floor(rawCurrentTime);

                let lastTime =
                    watchDurations[assignId] || 0;

                const now = Date.now();

                const previousSample =
                    lastPlayerSamples[assignId] || {
                        videoTime: rawCurrentTime,
                        wallTime: now
                    };

                const wallElapsedSeconds = Math.max(
                    0.25,
                    (now - previousSample.wallTime) / 1000
                );

                const videoAdvance =
                    rawCurrentTime -
                    previousSample.videoTime;

                /*
                 * Tốc độ hợp lệ duy nhất là 1×, vì vậy giới hạn
                 * bước tiến chỉ dựa trên thời gian thực.
                 */
                const allowedAdvance =
                    wallElapsedSeconds + 3;

                /*
                 * Chặn cú nhảy ngay cả ở mẫu đầu tiên.
                 * Bản cũ có thể chấp nhận việc YouTube mở sẵn
                 * gần cuối video vì previousSample cũng bắt đầu
                 * ở chính vị trí cuối đó.
                 */
                const maxSequentialTime =
                    lastTime +
                    Math.max(
                        3.5,
                        allowedAdvance
                    );

                if (
                    rawCurrentTime >
                    maxSequentialTime
                ) {
                    if (
                        typeof player.seekTo ===
                        'function'
                    ) {
                        player.seekTo(
                            lastTime,
                            true
                        );
                    }

                    lastPlayerSamples[
                        assignId
                    ] = {
                        videoTime:
                            lastTime,
                        wallTime:
                            now
                    };

                    return;
                }

                if (currentTime > lastTime) {
                    if (
                        currentTime - lastTime > 5 &&
                        videoAdvance > allowedAdvance
                    ) {
                        player.seekTo(lastTime, true);

                        lastPlayerSamples[assignId] = {
                            videoTime: lastTime,
                            wallTime: now
                        };

                        return;
                    } else {
                        // Hợp lệ -> Đẩy đồng hồ lên
                        watchDurations[assignId] = currentTime;

                        saveLocalVideoProgress(
                            assignId,
                            currentTime
                        );

                        updateVideoWatchDisplays(
                            assignId,
                            currentTime
                        );

                        // =====================================================
                        // LƯU TIẾN ĐỘ ĐỊNH KỲ
                        // =====================================================
                        const savedTime = Number(lastSavedTime[assignId]) || 0;

                        // Không dùng currentTime % 5 vì bộ đếm có thể nhảy qua đúng mốc.
                        if (currentTime - savedTime >= 5) {
                            db.ref(
                                `video_tracking/${assignId}/${currentUser.username}`
                            ).transaction(oldValue => {
                                const oldSeconds = Number(oldValue) || 0;

                                // Chỉ cho phép tiến độ tăng, không bị tab cũ ghi tụt xuống.
                                return Math.max(oldSeconds, currentTime);
                            }).then(result => {
                                if (result.committed) {
                                    lastSavedTime[assignId] =
                                        Number(result.snapshot.val()) || currentTime;
                                }
                            }).catch(error => {
                                console.error(
                                    "Không thể lưu tiến độ xem video:",
                                    error
                                );
                            });
                        }

                        // =====================================================
                        // KIỂM TRA MỞ KHÓA Ở MỖI GIÂY XEM HỢP LỆ
                        // =====================================================
                        const currentAssign = Array.isArray(window.cachedAssignments)
                            ? window.cachedAssignments.find(
                                item => String(item.id) === String(assignId)
                            )
                            : null;

                        if (
                            currentAssign &&
                            Number(currentAssign.watchCondition) > 0 &&
                            currentTime >= Number(currentAssign.watchCondition)
                        ) {
                            // Chặn chạy mở khóa nhiều lần cùng lúc.
                            if (
                                !window[`unlocked_${assignId}`] &&
                                !window[`unlocking_${assignId}`]
                            ) {
                                window[`unlocking_${assignId}`] = true;

                                const progressRef = db.ref(
                                    `video_tracking/${assignId}/${currentUser.username}`
                                );

                                // Lưu mốc đạt yêu cầu trước rồi mở giao diện.
                                progressRef.transaction(oldValue => {
                                    const oldSeconds = Number(oldValue) || 0;
                                    return Math.max(oldSeconds, currentTime);
                                }).then(result => {
                                    if (!result.committed) {
                                        throw new Error("Không thể ghi tiến độ video");
                                    }

                                    const savedSeconds =
                                        Number(result.snapshot.val()) || currentTime;

                                    lastSavedTime[assignId] = Math.max(
                                        Number(lastSavedTime[assignId]) || 0,
                                        savedSeconds
                                    );

                                    window[`unlocked_${assignId}`] = true;

                                    window.updateVideoSummaryAccess(
                                        assignId,
                                        true,

                                        Number(
                                            currentAssign.watchCondition
                                        ) || 0
                                    );

                                    // Ẩn bảng cảnh báo yêu cầu xem video.
                                    const noticeBox = document.getElementById(
                                        `condition-notice-${assignId}`
                                    );

                                    if (noticeBox) {
                                        noticeBox.style.display = "none";
                                    }

                                    if (currentAssign.assessmentType === "thi") {
                                        // Bài thi: mở nút bắt đầu thi.
                                        const examWrapper = document.getElementById(
                                            `exam-wrapper-${assignId}`
                                        );

                                        if (examWrapper) {
                                            examWrapper.style.display = "block";

                                            setTimeout(() => {
                                                examWrapper.scrollIntoView({
                                                    behavior: "smooth",
                                                    block: "center"
                                                });
                                            }, 100);
                                        }
                                    } else {
                                        // Bài thường: mở phần làm bài ngay.
                                        const contentBox = document.getElementById(
                                            `assignment-task-content-${assignId}`
                                        );

                                        if (contentBox) {
                                            contentBox.style.display = "block";
                                            contentBox.style.opacity = "1";

                                            setTimeout(() => {
                                                contentBox.scrollIntoView({
                                                    behavior: "smooth",
                                                    block: "start"
                                                });
                                            }, 100);
                                        }
                                    }

                                    if (typeof window.showToast === "function") {
                                        window.showToast(
                                            "Đã đạt đủ thời lượng xem. Phần làm bài đã được mở khóa!",
                                            "success"
                                        );
                                    }
                                }).catch(error => {
                                    console.error(
                                        "Không thể mở khóa bài sau khi xem video:",
                                        error
                                    );
                                }).finally(() => {
                                    delete window[`unlocking_${assignId}`];
                                });
                            }
                        }
                    }
                }
                lastPlayerSamples[assignId] = {
                    videoTime:
                        Number(player.getCurrentTime()) || 0,
                    wallTime: Date.now()
                };
            }
        }, 1000);
    } else {
        if (watchTimers[assignId]) {
            clearInterval(
                watchTimers[assignId]
            );

            delete watchTimers[assignId];
        }

        delete lastPlayerSamples[assignId];

        if (watchDurations[assignId]) {
            saveVideoProgressToFirebase(
                assignId,
                watchDurations[assignId]
            );
        }
    }
};

